import React from 'react';
import ReactDOM from 'react-dom/client';
import Split from 'react-split';
import './UIModel.css';
import DetailBuilder from './Components/Details/DetailBuilder';
import IModule from '../Core/IModule';
import MainContentBuilder from './Components/MainContent/MainContentBuilder';
import WorldSettingsBuilder from './Components/WorldSettings/WorldSettingsBuilder';
import SceneTreeBuilder from './Components/SceneTree/SceneTreeBuilder';

/**
 * UI模块类
 */
class UIModel extends IModule {
    constructor(Config) {
        super();
        this.Config = Config;
        this.Root = null;
        this.Component = null;
        this.DetailBuilder = DetailBuilder.getInstance(this.HandleStateChange);
        this.WorldSettingsBuilder = WorldSettingsBuilder.getInstance(this.HandleStateChange);
        this.MainContentBuilder = MainContentBuilder.getInstance(this.HandleStateChange);
        this.SceneTreeBuilder = SceneTreeBuilder.getInstance();
        this.bInitialized = false;  // 添加初始化标志
    }

    /**
     * 初始化模块
     * @returns {Promise<void>}
     */
    async Initialize() {
        if (this.bInitialized) {
            console.warn('UIModel already initialized');
            return;
        }

        try {


            // 初始化React根节点
            const RootElementId = this.Config.Params.RootElementId || 'root';
            const rootElement = document.getElementById(RootElementId);

            // 检查是否已经有 Root 实例
            if (!this.Root) {
                this.Root = ReactDOM.createRoot(rootElement);
            }
            
            this.Component = React.createRef();


            // 渲染UI组件
            this.Root.render(
                <MainPage 
                    ref={this.Component}
                    manager={this.Manager}
                    config={this.Config}
                />
            );

            this.bInitialized = true;
            console.log('UIModel initialized');
        } catch (Error) {
            console.error('Failed to initialize UIModel:', Error);
            throw Error;
        }
    }

    /**
     * 更新模块
     * @param {number} DeltaTime - 时间增量（秒）
     */
    Update(DeltaTime) {
        if (this.Component?.current) {
            this.Component.current.forceUpdate();
        }
    }

    /**
     * 关闭模块
     * @returns {Promise<void>}
     */
    async Shutdown() {
        if (!this.bInitialized) return;

        try {
            // 卸载React应用
            if (this.Root) {
                this.Root.unmount();
                this.Root = null;
                this.Component = null;
            }
            this.bInitialized = false;
            console.log('UIModel shut down');
        } catch (Error) {
            console.error('Failed to shutdown UIModel:', Error);
            throw Error;
        }
    }

    /**
     * 获取UI管理器
     * @returns {UIModelManager}
     */
    GetManager() {
        return this.Manager;
    }

    /**
     * 获取细节构建器
     * @returns {DetailBuilder}
     */
    GetDetailBuilder() {
        return this.DetailBuilder;
    }

    GetMainContentBuilder() {
        return this.MainContentBuilder;
    }

}

// UI组件类
class MainPage extends React.Component {
    componentCache = new Map();
    
    constructor(props) {
        super(props);
        this.state = {
            activeTab: 'details',
            updateCounter: 0
        };
        this.manager = props.manager;
        
        // 绑定 handleStateChange
        this.handleStateChange = this.handleStateChange.bind(this);
        this.detailBuilder = DetailBuilder.getInstance(this.handleStateChange);
        this.worldSettingsBuilder = WorldSettingsBuilder.getInstance(this.handleStateChange);
        this.mainContentBuilder = MainContentBuilder.getInstance(this.handleCanvasEvent);
        // 添加 SceneTreeBuilder
        this.sceneTreeBuilder = SceneTreeBuilder.getInstance();
        // 设置结构变化回调
        this.sceneTreeBuilder.setStructureChangeCallback(() => {
            // 触发重新渲染
            this.setState(prevState => ({
                updateCounter: prevState.updateCounter + 1
            }));
        });

        // 绑定画布事件处理器
        this.handleCanvasEvent = this.handleCanvasEvent.bind(this);
    }

    // 实现 handleStateChange 方法
    handleStateChange = (path, value) => {
        // 触发重新渲染
        this.setState(prevState => ({
            updateCounter: prevState.updateCounter + 1
        }));
        
        // 如果需要，可以通过 manager 通知其他组件
        if (this.manager && typeof this.manager.onDetailChange === 'function') {
            this.manager.onDetailChange(path, value);
        }
    }

    handleCanvasEvent = (path, value) => {
        switch (path) {
            case 'canvas.ready':
                // 画布已就绪，可以开始渲染
                console.log('Canvas ready:', value);
                break;
            case 'canvas.resize':
                // 画布尺寸已改变
                console.log('Canvas resized:', value);
                break;
            case 'tools':
                // 工具状态改变
                console.log('Tools changed:', value);
                break;
            default:
                console.log('Main content event:', path, value);
        }

        // 触发重新渲染
        this.setState(prevState => ({
            updateCounter: prevState.updateCounter + 1
        }));
    }

    switchTab = (tabName) => {
        this.setState({ activeTab: tabName });
    }

    render() {
        const { activeTab } = this.state;

        return (
            <div className="ui-model-container">
                <Split sizes={[20, 60, 20]} minSize={50} gutterSize={4} className="split-horizontal">
                    <div className="left-panel">
                        <div className="panel-header">
                            <h3>放置Actor</h3>
                            <button className="close-button">×</button>
                        </div>
                        <div className="search-box">
                            <input type="text" placeholder="搜索类" />
                        </div>
                        <div className="category-icons"></div>
                        <div className="actor-list">
                        {/* 临时功能描述开始 */}
                        <div style={{
                            padding: '15px',
                            fontSize: '14px',
                            lineHeight: '1.6',
                            color: '#e0e0e0',
                            backgroundColor: 'rgba(30, 30, 30, 0.7)',
                            borderRadius: '8px',
                            border: '1px solid #444'
                        }}>
                            <h3 style={{
                                fontSize: '18px',
                                fontWeight: 'bold',
                                marginBottom: '12px',
                                color: '#4fc3f7',
                                textShadow: '0 0 2px rgba(79, 195, 247, 0.5)'
                            }}>该区域用于放置Actor，当前版本临时用于功能描述：</h3>
                            
                            <div style={{marginBottom: '18px'}}>
                                <h4 style={{
                                    fontWeight: 'bold', 
                                    marginBottom: '8px',
                                    color: '#81c784',
                                    fontSize: '16px'
                                }}>1. 操作：（于UE类似）</h4>
                                <ul style={{paddingLeft: '20px', listStyleType: 'disc'}}>
                                    <li style={{marginBottom: '5px'}}>右键长按视口+WASD移动</li>
                                    <li style={{marginBottom: '5px'}}>右键长按视口+鼠标移动旋转</li>
                                    <li style={{marginBottom: '5px'}}>右键长按视口+滚轮调整移动速度</li>
                                    <li style={{marginBottom: '5px'}}>右键长按视口+QE垂直移动</li>
                                </ul>
                            </div>
                            
                            <div style={{marginBottom: '18px'}}>
                                <h4 style={{
                                    fontWeight: 'bold', 
                                    marginBottom: '8px',
                                    color: '#81c784',
                                    fontSize: '16px'
                                }}>2. 世界场景设置：</h4>
                                <div style={{paddingLeft: '20px'}}>
                                    <h5 style={{
                                        fontWeight: 'bold', 
                                        marginBottom: '8px',
                                        color: '#ffb74d',
                                        fontSize: '15px'
                                    }}>2.1 缓冲显示：</h5>
                                    <ul style={{paddingLeft: '20px', listStyleType: 'circle'}}>
                                        <li style={{marginBottom: '5px'}}>场景深度</li>
                                        <li style={{marginBottom: '5px'}}>世界法线（<span style={{color: '#ff8a65'}}>GBufferA</span>）</li>
                                        <li style={{marginBottom: '5px'}}>SMR（<span style={{color: '#ff8a65'}}>GBufferB</span>）：Specular，metallic，roughness 分别占用一个RGB通道</li>
                                        <li style={{marginBottom: '5px'}}>BaseColor（<span style={{color: '#ff8a65'}}>GBufferC</span>）</li>
                                        <li style={{marginBottom: '5px'}}>additional（<span style={{color: '#ff8a65'}}>GBufferD</span>）：暂时未使用</li>
                                        <li style={{marginBottom: '5px'}}>光照和阴影</li>
                                    </ul>
                                    
                                    <h5 style={{
                                        fontWeight: 'bold', 
                                        marginTop: '12px', 
                                        marginBottom: '8px',
                                        color: '#ffb74d',
                                        fontSize: '15px'
                                    }}>2.2 camera：</h5>
                                    <p style={{paddingLeft: '20px'}}>当前视口camera信息</p>
                                </div>
                            </div>
                            
                            <div style={{marginBottom: '18px'}}>
                                <h4 style={{
                                    fontWeight: 'bold', 
                                    marginBottom: '8px',
                                    color: '#81c784',
                                    fontSize: '16px'
                                }}>3. 细节：</h4>
                                <p style={{paddingLeft: '20px'}}>显示当前单个选择的Object信息——配合右上角场景树使用</p>
                            </div>
                            
                            <div style={{marginBottom: '10px'}}>
                                <h4 style={{
                                    fontWeight: 'bold', 
                                    marginBottom: '8px',
                                    color: '#81c784',
                                    fontSize: '16px'
                                }}>4. 场景树：</h4>
                                <p style={{paddingLeft: '20px'}}>选中单个物体在其下显示细节信息（暂未实现选中描边）</p>
                            </div>
                        </div>
                        {/* 临时功能描述结束 */}
                        </div>
                    </div>

                    <Split
                        direction="vertical"
                        sizes={[70, 30]}
                        minSize={50}
                        gutterSize={4}
                        className="main-content-container"
                    >
                        <div className="main-content-top">
                            {this.mainContentBuilder.build()}
                        </div>
                        <div className="main-content-bottom">
                            <div className="content-browser">
                                <div className="browser-content">
                                    <Split
                                        sizes={[30, 70]}
                                        minSize={100}
                                        gutterSize={4}
                                        className="split-horizontal file-management-split"
                                    >
                                        <div className="file-tree"></div>
                                        <div className="file-details">
                                            <div className="file-details-header">
                                                <div className="browser-search">
                                                    <input type="text" placeholder="搜索" />
                                                </div>
                                            </div>
                                            <div className="file-details-content"></div>
                                        </div>
                                    </Split>
                                </div>
                            </div>
                        </div>
                    </Split>

                    <Split
                        direction="vertical"
                        sizes={[30, 70]}
                        minSize={50}
                        gutterSize={4}
                        className="right-panel-container"
                    >
                        <div className="right-panel-top">
                            <div className="outline-header">
                                <div className="outline-controls">
                                    <span className="item-label">Item Label ▾</span>
                                    <span className="type-label">类型</span>
                                </div>
                                <div className="outline-search">
                                    <input type="text" placeholder="搜索" />
                                </div>
                            </div>
                            <div className="outline-content">
                                {this.sceneTreeBuilder.build()}
                            </div>
                        </div>
                        <div className="right-panel-bottom">
                            <div className="tab-header">
                                <button
                                    className={`tab-button ${activeTab === 'details' ? 'active' : ''}`}
                                    onClick={() => this.switchTab('details')}
                                >
                                    细节
                                </button>
                                <button
                                    className={`tab-button ${activeTab === 'worldSettings' ? 'active' : ''}`}
                                    onClick={() => this.switchTab('worldSettings')}
                                >
                                    世界场景设置
                                </button>
                            </div>
                            <div className="tab-content">
                                {activeTab === 'details' ? (
                                    <div className="details-content">
                                        {this.detailBuilder.build()}
                                    </div>
                                ) : (
                                    <div className="world-settings-content">
                                        {this.worldSettingsBuilder.build()}
                                    </div>
                                )}
                            </div>
                        </div>
                    </Split>
                </Split>
            </div>
        );
    }
}

export default UIModel;
